"""Reviewed routes, not a promise of access or measured regional coverage."""
from urllib.parse import urlencode
from .sources import POLICIES

# Region/language descriptions describe source focus, not demonstrated coverage.
ROUTES = [
 ('Wuzzuf','A','Egypt','Arabic / English','access_blocked_current_check','https://wuzzuf.net/policies','User reports provider authorization. An earlier ordinary-browser sample collected four jobs, but the current restoration check was blocked in both direct HTTP and ordinary-browser paths. Current access is not verified working. See docs/SCRAPER_RESTORATION.md. No challenge bypass; robots mode remains scoped and optional.', 'wuzzuf.net'),
 ('Naukrigulf','A','Gulf / Middle East','English / Arabic','authorized_browser_sample_verified','https://www.naukrigulf.com/terms-and-conditions','User reports provider authorization. On 2026-10-29 the explicit ordinary-browser route ingested 4 genuine jobs after waiting for publisher JSON-LD, with a committed checkpoint. Direct HTTP still timed out. Sample only, not coverage. No challenge bypass; robots mode remains scoped and optional.', 'naukrigulf.com'),
 ('Major and regional boards','A','Global / regional','Source dependent','unverified','https://www.indeed.com/','Original JobSpy job-search adapters for Indeed/LinkedIn are reconnected; Bayt added. Configured searches rotate through Egypt, Oman, UAE, Germany and remote (plus Austria/Switzerland). Google adapter retained but currently fails upstream. Glassdoor, Monster and StepStone are not configured. Access varies; see live source report.', ''),
 ('Workday employer careers','B','Employer dependent','Tenant dependent','authorization_required','https://developer.workday.com/api-overview','Original DirectAPIScanner retained and repaired. Explicit public Workday tenant/board CXS configuration supported; private REST APIs still need authorization. No Workday tenant was configured in the attached original. Bosch SmartRecruiters account/detail/pagination handling repaired.', 'myworkdayjobs.com'),
 ('Search engines / Google Jobs','C','Global','Query dependent','manual','https://www.google.com/search','Open search in your browser; no server-side search scraping or assumed free Google Jobs API. Search results are leads, not verified vacancies.', ''),
 ('LinkedIn / X hiring posts','D','Global','Post dependent','authorization_required','https://www.linkedin.com/legal/user-agreement','Explicit official-API adapters exist: LinkedIn authorized organization posts only; X public-user timelines with separate access/cost consent. No tokens or IDs supplied, so not connected or live verified. Authorized exports also supported. Complete vacancies can be auto-added, ambiguous posts need review.', ''),
 ('Reddit communities','E','Community dependent','Community dependent','authorization_required','https://support.reddithelp.com/hc/en-us/articles/42728983564564-Responsible-Builder-Policy','Official OAuth subreddit new-post adapter requires approved API use, token and scoped subreddit. No credentials supplied or live verification. No RSS/HTML workaround. Authorized exports also supported.', 'reddit.com'),
 ('Telegram / Discord / forums','E','Community dependent','Community dependent','unverified','https://discord.com/developers/docs/intro','Telegram: dedicated bot update queue plus explicit public-channel allowlist, not history scraping. Discord: authorized guild/channel IDs and bot content/history permissions, no DMs or user tokens. Forums: permitted RSS/Atom or authorized exports, no universal HTML crawler. Configuration required; no live verification.', ''),
 ('Agency vacancy pages','F','Agency dependent','Source dependent','manual','https://www.hays.com/','Vacancy listings only; no recruiter identity discovery, people-data harvesting or outreach. Official site or independently authorized feed/import.', ''),
 ('Universities / research / NGOs','G','Organization dependent','Source dependent','manual','https://careers.un.org/','UN/academic/employer careers can be searched manually. No universal API or coverage claim; permitted feeds and canonical file imports are supported.', ''),
 ('Freelance / contract platforms','H','Global','Source dependent','unverified','https://www.upwork.com/','No platform adapter or account access. Use official search; only import content with sufficient rights. No bids or messages are submitted.', ''),
 ('Himalayas','H','Remote','English','policy_review','https://himalayas.app/docs/remote-jobs-api','Documented public API, not implemented here. Attribution, expiration and redistribution limits require deployment-specific review.', 'himalayas.app'),
 ('Startup / VC portfolio careers','I','Portfolio dependent','Source dependent','manual','https://www.ycombinator.com/jobs','Official search or a separately approved supported employer ATS board. No portfolio-wide completeness claim.', ''),
 ('We Work Remotely RSS','J','Remote','English','implemented','https://weworkremotely.com/api-terms-and-guidelines','Dedicated public RSS collector implemented with company/title, region, type, description and date. Publisher attribution and backlink retained. Current feed only; no full-site claim.', 'weworkremotely.com'),
 ('Permitted RSS / Atom / newsletters','J','Feed dependent','Feed dependent','implemented','https://www.rssboard.org/rss-specification','Approved public HTTPS feeds and local RSS/Atom files supported; social hosts/private targets blocked. Newsletter text only with rights; no mailbox connection.', ''),
 ('User supplied files and copied descriptions','K','User selected','Input dependent','implemented','https://schema.org/JobPosting','Canonical CSV/JSON/JSONL and optional Excel supported; copied post text enters review. No arbitrary webpage fetch or JSON-LD parser. Narrow email integration remains unimplemented.', ''),
 ('Additional sources','L','Unmeasured','Unmeasured','assessment_required','https://schema.org/JobPosting','Assess first-party documentation, reuse terms, auth/cost and test fixtures before adding a static adapter. No automatic adapter generation or activation.', ''),
]

def directory(query=''):
    if not isinstance(query,str) or len(query)>200 or any(ord(c)<32 for c in query): raise ValueError('Search query must be at most 200 printable characters')
    result=[]
    for name,category,region,languages,status,evidence,notice,domain in ROUTES:
        result.append({'name':name,'category':category,'regions':region,'languages':languages,'status':status,'evidence':evidence,'limitations':notice,'reviewed_on':'2026-10-29','live_verified':status=='authorized_browser_sample_verified','live_verification_scope':'One browser listing + four details per board on 2026-10-29; not whole-site or direct-HTTP verification' if status=='authorized_browser_sample_verified' else 'Not verified','auth_configuration':'No credentials configured by the directory','cost':'No paid integration enabled','search_url':'https://www.google.com/search?'+urlencode({'q':('site:'+domain+' ' if domain else '')+(query or name+' jobs')}),'collection':'Explicit HTTP or optional dedicated-browser collector; scoped robots mode; at most five/six top-level navigations in browser mode plus normal browser resource requests; one-hour provider cooldown' if status=='authorized_browser_sample_verified' else 'manual / supplied content' if status!='implemented' else 'existing feed/import workflow'})
    for kind,p in POLICIES.items():
        if kind in ('feed','wuzzuf','naukrigulf'): continue
        result.append({'name':kind,'category':'D' if kind in ('linkedin','x') else 'E' if kind in ('reddit','telegram','discord') else 'G' if kind=='usajobs' else 'D' if kind=='hn' else 'H' if kind in ('jobicy','arbeitnow','remotive') else 'B','regions':'US federal' if kind=='usajobs' else 'Germany / UK focus' if kind=='arbeitnow' else 'Source dependent; unmeasured','languages':'Source dependent; unmeasured','status':'implemented_auth_required' if kind in ('usajobs','linkedin','x','reddit','telegram','discord') else 'implemented','evidence':p['docs'],'limitations':p['notice'],'reviewed_on':'2026-10-29','live_verified':False,'auth_configuration':'USAJOBS_API_KEY + USAJOBS_USER_AGENT environment only' if kind=='usajobs' else 'No credential used','cost':'Free documented route; Jobicy paid key deliberately unsupported' if kind=='jobicy' else 'No paid access enabled','search_url':'https://www.google.com/search?'+urlencode({'q':query or kind+' jobs'}),'collection':f'Manual static adapter; max {p["requests"]} requests per scan; cooldown {p["cooldown"]} seconds'})
    return result
